/* ===== Beginner layer: plain-English intros, new words, problem briefs =====
   EASY[topicId] = { p: plain-English explanation (HTML), w: [[term, simple meaning], ...] }
   The technical notes stay untouched; this sits on top as a "start here". */
const EASY={
/* ---------- World 1: Foundations ---------- */
"what-is-sd":{p:`<p>Think of building a restaurant. One cook in a tiny kitchen works for 10 customers. For 10,000 customers a day you need more cooks, a bigger kitchen, a pantry, a waiter system, and a plan for when the oven breaks. <b>System design is that planning, for software.</b></p><p>You decide which "parts" an app needs (servers, databases, caches, queues), how they pass data to each other, and what you give up to get what you want. There is never one perfect answer, so interviewers mostly check whether you can explain <i>why</i> you chose something.</p>`,
w:[["Server","A computer that runs your app's code and answers requests from users."],["Database (DB)","The place where data is stored permanently, like users, orders and messages."],["HLD","High-level design: the big boxes-and-arrows picture of a whole system."],["LLD","Low-level design: the classes, methods and code structure inside one part."],["Trade-off","Getting more of one good thing by accepting less of another, e.g. speed vs cost."],["Scale","Handling more users, data or requests without breaking or slowing down."]]},
"scalability":{p:`<p>Your app gets popular and one server can't keep up. You have two choices. <b>Vertical scaling</b>: buy a bigger, stronger computer (like swapping a scooter for a truck). Easy, but there's a size limit and it's still one machine. <b>Horizontal scaling</b>: add more ordinary computers and share the work (like adding more scooters to a delivery fleet). No real limit, but now something has to hand out the work.</p><p>The catch: horizontal only works if any server can answer any user. So servers shouldn't remember users in their own memory (that's what <b>stateless</b> means). The memory goes into a shared database or cache instead.</p>`,
w:[["Vertical scaling","Making one machine bigger: more CPU, RAM or disk."],["Horizontal scaling","Adding more machines that share the work."],["Load balancer","A traffic cop that spreads incoming requests across many servers."],["Stateless","A server that keeps no user data between requests, so any server can handle any request."],["Session","Data about a logged-in user's visit, like who they are or what's in their cart."]]},
"availability":{p:`<p><b>Availability</b> asks: when a user opens the app, does it work? It's measured as a percentage of time the system is up. 99.9% sounds great, but it still means about 8.8 hours of downtime a year.</p><p>The enemy is a <b>single point of failure</b>: one part that takes everything down if it dies, like a house with one door that jams. The fix is <b>redundancy</b> (have two or more of everything important) plus <b>failover</b> (switch to the spare automatically when the main one dies).</p>`,
w:[["Availability","The percentage of time a system is up and answering users."],["Nines","Shorthand for availability: \"three nines\" = 99.9%, \"four nines\" = 99.99%."],["SPOF","Single point of failure: one part whose failure brings the whole system down."],["Redundancy","Keeping spare copies of parts so one failure doesn't stop the system."],["Failover","Automatically switching to a backup when the main part fails."],["Reliability","Whether the system gives correct results consistently over time, not just whether it's up."]]},
"latency":{p:`<p>Picture a coffee shop. <b>Latency</b> is how long <i>you</i> wait for your coffee. <b>Throughput</b> is how many coffees the shop serves per hour. A shop can serve lots of people (high throughput) while each person still waits a while (high latency).</p><p>We look at the slowest users, not the average, because an average hides the unlucky ones. "p99 = 300 ms" means 99 of 100 requests finish within 300 milliseconds. You also learn rough speeds: reading memory is far faster than reading a disk, which is far faster than sending data across the world.</p>`,
w:[["Latency","How long one request takes from start to finish."],["Throughput","How many requests the system completes per second."],["ms (millisecond)","One thousandth of a second. 1,000 ms = 1 s."],["p99 / percentile","p99 = the time within which 99% of requests finish; it shows the slow tail."],["RAM","Random-access memory: very fast, temporary storage inside a computer; lost when power goes off."],["SSD / disk","Slower, permanent storage that survives restarts."]]},
"cap":{p:`<p>Imagine two bank branches that share account data by phone. One day the phone line is cut (a <b>partition</b>). A customer wants to withdraw money at branch A. Branch A has two choices: <b>refuse</b> until the line is back, so the balance stays correct (Consistency), or <b>allow it</b> and sort things out later, which risks wrong balances (Availability).</p><p>That's CAP: when machines can't talk, you must pick correct-but-maybe-unavailable or available-but-maybe-stale. PACELC adds that even on a normal day, waiting for every copy to agree makes things slower.</p>`,
w:[["Distributed system","Many computers working together and appearing to users as one system."],["Partition","A network break where some machines can't talk to others."],["Consistency (in CAP)","Every read sees the most recent write, as if there were one copy."],["Stale data","Old data that hasn't caught up with the latest change yet."],["Replica","A copy of the data kept on another machine."],["Quorum","A majority of copies that must agree before a read or write counts."]]},

/* ---------- World 2: Networking & APIs ---------- */
"internet":{p:`<p>When you type a website address, a lot happens in under a second. First your computer looks up the site's numeric address (<b>DNS</b>, like a phone book). Then it opens a connection and both sides confirm they can hear each other (the <b>TCP handshake</b>). Next they agree on a secret code so nobody can snoop (<b>TLS</b>, the "s" in https). Finally your browser sends an <b>HTTP request</b> ("give me this page") and the server sends a response.</p><p><b>TCP</b> is like registered post: everything arrives, in order. <b>UDP</b> is like shouting across a room: faster, but some words get lost. That's fine for video calls and games.</p>`,
w:[["IP address","The numeric address of a computer on the internet, e.g. 142.250.183.14."],["DNS","The internet's phone book: turns names like google.com into IP addresses."],["TCP","A reliable way to send data: checks everything arrives, in order."],["UDP","A fast way to send data with no delivery guarantee."],["TLS / HTTPS","Encryption that keeps data private between browser and server."],["HTTP","The request/response language browsers and servers speak (GET, POST…)."],["Status code","A 3-digit result like 200 (OK), 404 (not found), 500 (server error)."]]},
"dns-cdn":{p:`<p><b>DNS</b> turns a name like <i>youtube.com</i> into an IP address. Answers are saved (cached) at several levels so most lookups are instant.</p><p>A <b>CDN</b> is a network of servers spread around the world that keep copies of your files (images, videos, scripts). It's like a chain store with branches in every city: a user in Chennai gets the video from a nearby server instead of one in the US. That's faster for users and takes load off your main server (the <b>origin</b>).</p>`,
w:[["Cache","A saved copy of data kept somewhere fast so you don't fetch it again."],["TTL","Time to live: how long a cached copy is trusted before it's refreshed."],["CDN","Content delivery network: servers worldwide holding copies of files near users."],["Edge server","A CDN server located close to users."],["Origin","Your own main server that holds the original files."],["Static content","Files that are the same for everyone, like images, CSS and JS."]]},
"proxies-lb":{p:`<p>A <b>proxy</b> is a middleman. A <b>forward proxy</b> stands in front of <i>users</i> (like a school network filter). A <b>reverse proxy</b> stands in front of <i>servers</i>, so users talk to it and never see the servers behind.</p><p>A <b>load balancer</b> is a reverse proxy whose job is to spread requests across many servers, like a supermarket manager sending customers to the shortest checkout line. An <b>API gateway</b> is a smarter front door for many services: it checks who you are, limits abuse, and routes each request to the right service.</p>`,
w:[["Proxy","A middleman computer that passes requests along on someone's behalf."],["Reverse proxy","A middleman in front of servers; users only see the proxy."],["Load balancer","Spreads incoming requests across a group of servers."],["Health check","A regular \"are you alive?\" ping so traffic avoids dead servers."],["L4 / L7","Network layers: L4 routes by address and port, L7 can read the HTTP request (URL, headers)."],["API gateway","A single front door that handles login checks, rate limits and routing for many services."]]},
"api-styles":{p:`<p>An <b>API</b> is a menu of things one program can ask another to do. There are three popular styles. <b>REST</b> is like ordering by item names ("GET /orders/42"); simple and works everywhere, so it's the default for public APIs. <b>gRPC</b> is like a speed-dial between kitchens: very fast, strict formats, great for services talking to each other inside a company. <b>GraphQL</b> lets the client say exactly which fields it wants in one request; handy when many apps need different shapes of the same data.</p>`,
w:[["API","Application programming interface: the set of requests one program accepts from another."],["Endpoint","One specific URL + method in an API, like POST /orders."],["JSON","A simple text format for data: {\"name\":\"Asha\",\"age\":21}."],["REST","An API style built on URLs for things (resources) and HTTP verbs for actions."],["gRPC","A fast, strongly typed API style for service-to-service calls."],["GraphQL","An API style where the client asks for exactly the fields it needs."]]},
"api-design":{p:`<p>A good API is easy to guess. Use <b>nouns</b> for things (<code>/users</code>, <code>/orders</code>) and HTTP <b>verbs</b> for actions (GET to read, POST to create, PATCH to edit, DELETE to remove).</p><p>Don't return a million rows at once: hand them out in pages (<b>pagination</b>), like a book. And plan for retries. If a "pay ₹500" request times out and the app tries again, the user mustn't be charged twice. An <b>idempotency key</b> is a unique ID sent with the request so the server can say "I've already done this one".</p>`,
w:[["Resource","A thing your API exposes, like a user, order or file."],["HTTP verbs","GET (read), POST (create), PUT/PATCH (update), DELETE (remove)."],["Pagination","Returning results in pages instead of all at once."],["Cursor","A bookmark that says \"continue after this item\" for the next page."],["Idempotent","Doing it twice has the same effect as doing it once."],["Versioning","Keeping old API versions (v1, v2) working while you change things."]]},
"realtime":{p:`<p>Normally the browser asks and the server answers. But chat and live scores need the server to <b>push</b> updates. Options, from simplest: <b>short polling</b> (asking "anything new?" every few seconds, like a kid asking "are we there yet?"); <b>long polling</b> (asking once and the server waits to reply until there's news); <b>SSE</b> (the server keeps a one-way stream open and sends updates down it); <b>WebSockets</b> (a two-way phone line that stays open, so both sides can talk any time).</p>`,
w:[["Polling","The client repeatedly asks the server whether there's new data."],["Push","The server sends data without being asked again."],["SSE","Server-sent events: a one-way stream from server to browser."],["WebSocket","A long-lived two-way connection between browser and server."],["Full duplex","Both sides can send at the same time."],["Pub/sub","Publish/subscribe: senders publish to a topic, everyone subscribed receives it."]]},
"auth":{p:`<p>Two separate questions. <b>Authentication</b>: who are you? (showing your ID card at the gate). <b>Authorization</b>: what are you allowed to do? (your card opens the library but not the staff room).</p><p>After login, the server must remember you. A <b>session</b> is like a cloakroom token: you hold a ticket number and the server keeps the details, so it can cancel your ticket any time. A <b>JWT</b> is like a signed wristband carrying your details: the server just checks the signature, but it's hard to take back before it expires. <b>OAuth</b> is "Log in with Google": you let one app access another without sharing your password.</p>`,
w:[["Authentication (AuthN)","Proving who you are, e.g. with a password."],["Authorization (AuthZ)","Deciding what a logged-in user is allowed to do."],["Session","Login info stored on the server; the browser keeps only an ID in a cookie."],["Cookie","A small piece of data the browser stores and sends back with each request."],["JWT","JSON Web Token: a signed token that carries user info, checked without a DB lookup."],["OAuth 2.0","A standard for giving an app limited access to another service on your behalf."],["Hashing","Turning a password into scrambled text that can't be reversed."]]},

/* ---------- World 3: Data & Storage ---------- */
"sql-nosql":{p:`<p><b>SQL databases</b> (PostgreSQL, MySQL) store data in tables with fixed columns, like a well-organised spreadsheet, and let you join tables together ("show each order with its customer's name"). They're strict and safe, which is great for money and bookings.</p><p><b>NoSQL databases</b> (MongoDB, DynamoDB, Cassandra) trade some of that structure for easy spreading across many machines or flexible data shapes. A good beginner rule: <b>start with SQL</b>, and switch only when you can say exactly why, e.g. "billions of simple key lookups a day".</p>`,
w:[["Table / row / column","SQL data layout: a table of rows (records) with named columns (fields)."],["Schema","The fixed structure of your data: which tables and columns exist."],["Join","Combining rows from two tables that share a key."],["Primary key","A unique ID for each row, like order_id."],["Key-value store","A NoSQL DB that maps a key to a value, like a giant dictionary."],["Document store","A NoSQL DB that stores JSON-like documents, e.g. MongoDB."]]},
"acid":{p:`<p>A <b>transaction</b> is a group of database changes that must happen together. Moving ₹100 from Asha to Ravi means "take from Asha" <i>and</i> "give to Ravi". If only half happens, money vanishes.</p><p><b>ACID</b> is the promise: <b>A</b>tomic (all or nothing), <b>C</b>onsistent (rules like "balance ≥ 0" always hold), <b>I</b>solated (two transactions at once don't mess each other up), <b>D</b>urable (once saved, it survives a crash). <b>Isolation levels</b> let you choose how strictly transactions are kept apart: stricter is safer but slower.</p>`,
w:[["Transaction","A group of DB changes that succeed or fail together."],["Commit / rollback","Commit = save the transaction; rollback = undo all of it."],["Atomic","All steps happen, or none do."],["Durable","Saved data survives crashes and restarts."],["Concurrency","Many things happening at the same time."],["Lock","A rule that stops others changing a row while you use it."]]},
"indexing":{p:`<p>Finding one name in an unsorted list of a million means reading every row. An <b>index</b> is like the index at the back of a textbook: a sorted list that points straight to the right page. Reads become super fast.</p><p>The cost: every time you add or change data, the index must be updated too, and it takes extra space. So index the columns you search by often, not everything. <b>B-trees</b> are the usual index in SQL databases. <b>LSM trees</b> are built for databases that write a lot, like Cassandra.</p>`,
w:[["Index","An extra structure that makes lookups fast, like the index at the back of a book."],["Full table scan","Reading every row because no index helps."],["B-tree","A balanced, sorted tree; the standard index in SQL databases."],["LSM tree","A write-friendly structure that buffers writes in memory, then saves sorted files."],["Composite index","One index on several columns, e.g. (user_id, created_at)."],["Query","A request to the database, e.g. SELECT … WHERE …"]]},
"replication":{p:`<p><b>Replication</b> means keeping copies of the same data on several machines. If one dies, another has the data (availability), and reads can be shared across copies (speed).</p><p>Usually one copy is the <b>leader</b>: all writes go there, and it forwards changes to the <b>followers</b>, which handle reads. If forwarding happens in the background (<b>async</b>), followers can be a moment behind. That's why you might post a comment, refresh, and briefly not see it. That delay is <b>replication lag</b>.</p>`,
w:[["Replica","A copy of the database on another machine."],["Leader","The copy that accepts writes (also called the primary)."],["Follower","A copy (also called a secondary) that receives changes from the leader and serves reads."],["Sync / async","Sync: wait for copies before saying \"saved\". Async: say \"saved\" first, copy later."],["Replication lag","How far behind a follower is from the leader."],["Read-your-writes","A guarantee that you always see your own latest changes."]]},
"sharding":{p:`<p>When one database machine can't hold all the data or handle all the writes, you split the data across several machines. Each piece is a <b>shard</b>. It's like a library splitting books across floors: A–F on floor 1, G–M on floor 2, and so on.</p><p>The big decision is the <b>shard key</b>, the field you split by. A good key spreads data evenly and keeps things you query together on the same shard. A bad key, like splitting by date, sends all today's traffic to one overloaded shard (a <b>hot spot</b>).</p>`,
w:[["Shard","One slice of the data, stored on its own machine."],["Sharding / partitioning","Splitting data across machines so each holds part of it."],["Shard key","The field used to decide which shard a record lives on."],["Hot spot / hot shard","One shard getting far more traffic than the others."],["Rebalancing","Moving data between shards when you add machines or load is uneven."],["Cross-shard query","A query that needs data from several shards; slower and harder."]]},
"consistent-hashing":{p:`<p>A simple way to pick a server for a key is <code>hash(key) % N</code>. But change N (add one server) and almost every key moves: a disaster for caches.</p><p><b>Consistent hashing</b> puts servers and keys on a circle (a ring). Each key belongs to the next server clockwise. Add a server and only the keys between it and its neighbour move, roughly 1/N of them. To keep things even, each real server appears at many spots on the ring (<b>virtual nodes</b>).</p>`,
w:[["Hash function","Turns any input into a fixed-size number; same input → same number."],["Modulo (%)","The remainder after division: 17 % 5 = 2."],["Hash ring","A circle of hash values where both servers and keys are placed."],["Virtual node","One real server placed at many points on the ring to spread load evenly."],["Rehashing","Recomputing where keys go after the number of servers changes."]]},
"caching":{p:`<p>A <b>cache</b> keeps frequently used data in fast memory, like keeping your phone charger on your desk instead of in the store room. Reading from a cache like Redis takes about a millisecond instead of many for a database query, and it takes load off the database.</p><p>The most common pattern, <b>cache-aside</b>: check the cache, and if it's not there (a <b>miss</b>), read the DB and save a copy in the cache. Caches are small, so old items get thrown out (<b>eviction</b>). <b>LRU</b> throws out whatever was used least recently. A <b>TTL</b> makes entries expire so data doesn't stay stale forever.</p>`,
w:[["Cache hit / miss","Hit: data was in the cache. Miss: it wasn't, so you go to the DB."],["Redis","A very popular in-memory data store used as a cache."],["Cache-aside","App checks cache → on miss reads DB → writes the result into the cache."],["Write-through","Every write updates the cache and DB together."],["Eviction","Removing items from a full cache to make room."],["LRU","Least recently used: evict whatever hasn't been touched for longest."],["TTL","Time to live: how long a cached item lives before it expires."]]},
"cache-problems":{p:`<p>Caches break in a few well-known ways. A <b>stampede</b>: a popular item expires and thousands of requests rush to the database at once. A <b>hot key</b>: one item, like a celebrity's post, is so popular that one cache server can't keep up. <b>Penetration</b>: people keep asking for things that don't exist, so the cache never helps and every request hits the DB. An <b>avalanche</b>: lots of items expire at the same moment.</p><p>Each has a standard fix, like letting only one request refill, caching "not found", or adding random jitter to expiry times. Knowing them makes you sound experienced.</p>`,
w:[["Stampede (thundering herd)","Many requests hitting the DB at once after a popular cache entry expires."],["Hot key","A single cache key receiving huge traffic."],["Cache penetration","Repeated requests for data that doesn't exist, bypassing the cache."],["Avalanche","Many cache entries expiring together, flooding the DB."],["Jitter","A small random amount added to times so things don't all happen at once."],["Bloom filter","A tiny structure that quickly says \"definitely not present\" or \"maybe present\"."]]},
"blob":{p:`<p>Photos, videos and PDFs are big. Putting them inside a database makes it slow and expensive. Instead, store files in <b>object storage</b> (like Amazon S3), a huge, cheap, reliable file warehouse, and keep only small details in the database (name, size, owner, where it's stored).</p><p>To keep your servers out of the way, the server hands the app a <b>presigned URL</b>: a temporary, signed link that lets the app upload or download that one file directly from S3. Big files are split into chunks so a failed upload can resume instead of restarting.</p>`,
w:[["Blob","Binary large object: a big file like an image or video."],["Object storage","A service (S3, GCS) that stores files as objects with an ID and metadata."],["Metadata","Data about data: file name, size, owner, created time."],["Presigned URL","A temporary signed link giving permission to upload or download one file."],["Chunking","Splitting a big file into pieces that upload separately."],["Multipart upload","Uploading a file in parts, then combining them on the server."]]},
"special-db":{p:`<p>A general database can do almost anything, but some jobs have a specialist tool that's far better. Searching text with typos and ranking ("cheap red shoes") → a <b>search engine</b> like Elasticsearch. Storing millions of readings over time (CPU every second) → a <b>time-series DB</b>. Finding "drivers within 2 km" → <b>geo indexes</b> like geohash or quadtrees. Finding "documents that mean the same as this question" → a <b>vector database</b> that searches by meaning.</p>`,
w:[["Inverted index","A map from each word to the list of documents containing it."],["Elasticsearch","A popular search engine for full-text search."],["Time-series DB","A DB optimised for data points stamped with time, like metrics."],["Geohash","A short string encoding a map area; nearby places share a prefix."],["Quadtree","A tree that keeps splitting a map into 4 squares until each has few points."],["Embedding","A list of numbers representing meaning, so similar texts get similar numbers."],["Vector search","Finding items whose embeddings are closest to a query's embedding."]]},

/* ---------- World 4: Async & Reliability ---------- */
"queues":{p:`<p>A <b>message queue</b> is like the order rail in a restaurant kitchen. The waiter (<b>producer</b>) clips an order and walks away; cooks (<b>consumers</b>) take orders when ready. The waiter doesn't wait for the food, and a rush of orders just makes the rail longer instead of breaking the kitchen.</p><p>Use queues for slow or bursty work: sending emails, processing videos, updating feeds. Messages might be delivered more than once, so consumers should handle duplicates safely. Messages that keep failing go to a <b>dead-letter queue</b> for a human to inspect. <b>Kafka</b> keeps a replayable log of events; <b>RabbitMQ/SQS</b> are classic task queues.</p>`,
w:[["Message queue","A buffer where messages wait until a worker processes them."],["Producer / consumer","Producer sends messages; consumer receives and processes them."],["Asynchronous (async)","Start the work now, finish it later, without making the user wait."],["Decoupling","Parts work independently, so one being slow or down doesn't block the other."],["At-least-once","Every message is delivered, but possibly more than once."],["Dead-letter queue (DLQ)","Where messages go after failing too many times."],["Kafka","A distributed log that stores events in order and lets many consumers read them."]]},
"rate-limit":{p:`<p>A <b>rate limiter</b> is a bouncer: "maximum 100 requests per minute per user". It stops abuse, bots and accidental floods from taking the service down.</p><p>The favourite algorithm is the <b>token bucket</b>. Each user has a bucket that refills with tokens at a steady speed; each request spends a token; an empty bucket means "429 Too Many Requests". It allows short bursts but keeps a fair average. With many servers, the counts live in a shared store like Redis so every server sees the same numbers.</p>`,
w:[["Rate limit","A cap on how many requests a user or client may make in a time window."],["Token bucket","Tokens refill steadily; each request uses one; no tokens = rejected."],["Fixed window","Count requests per clock minute; simple but allows bursts at the edges."],["Sliding window","Counts requests over the last N seconds, smoothing the edges."],["429","The HTTP status code for \"Too Many Requests\"."],["Burst","A short spike of many requests."]]},
"resilience":{p:`<p>In a big system, something is always failing somewhere. Calls get slow, servers restart, networks drop packets. So you design for it. <b>Timeouts</b>: don't wait forever. <b>Retries</b>: try again, waiting longer each time (<b>exponential backoff</b>) with some randomness (<b>jitter</b>) so everyone doesn't retry at the same instant.</p><p>A <b>circuit breaker</b> works like the one in your house: if a service keeps failing, stop calling it for a while so it can recover. And because retries can repeat work, make operations <b>idempotent</b> so doing them twice is harmless.</p>`,
w:[["Timeout","The maximum time you'll wait for a reply before giving up."],["Retry","Trying a failed request again."],["Exponential backoff","Waiting 1s, 2s, 4s, 8s… between retries."],["Jitter","Random extra delay so many clients don't retry in sync."],["Circuit breaker","Stops calling a failing service for a while, then tests it again."],["Bulkhead","Separate resource pools so one failure can't sink everything."],["Idempotent","Safe to repeat: twice has the same effect as once."]]},
"dist-txn":{p:`<p>Inside one database, a transaction keeps steps all-or-nothing. But booking a trip might touch a payment service, a hotel service and a flight service, each with its own database. No single transaction covers all three.</p><p><b>Two-phase commit (2PC)</b>: a coordinator asks everyone "ready?", then says "commit". Correct, but everyone waits and locks things meanwhile. A <b>saga</b> does each step separately and, if a later step fails, runs <b>compensating</b> steps (refund the payment, cancel the hotel). The <b>outbox pattern</b> makes sure "save to DB" and "tell other services" never get out of sync.</p>`,
w:[["Microservice","A small, separately deployed service that owns one job and its own data."],["2PC","Two-phase commit: prepare everyone, then commit everyone, via a coordinator."],["Saga","A chain of local steps with an undo (compensation) for each."],["Compensation","An action that reverses an earlier step, like a refund."],["Outbox pattern","Write the event into the same DB transaction, then publish it from there."],["Eventual consistency","Data may briefly disagree but will match up soon."]]},
"observability":{p:`<p>When something breaks at 2 a.m., how do you find out what and where? Three tools. <b>Metrics</b> are numbers over time (requests per second, error rate, latency), like a car's dashboard: they tell you <i>something</i> is wrong. <b>Traces</b> follow one request through every service, like a parcel tracking page, to show <i>where</i> it got slow. <b>Logs</b> are detailed text notes from the code that tell you <i>why</i>.</p><p>You set targets (<b>SLOs</b>, like "99.9% of requests succeed") and get alerted when users are actually affected, not for every small blip.</p>`,
w:[["Metric","A number measured over time, like errors per minute."],["Log","A timestamped text record of something that happened in the code."],["Trace","The path and timing of one request across all services."],["SLI","Service level indicator: what you measure, e.g. success rate."],["SLO","Service level objective: your target for it, e.g. 99.9% success."],["Alert","An automatic notification when a metric crosses a threshold."]]},
"architecture":{p:`<p>A <b>monolith</b> is one app containing everything: users, orders, payments. Simple to build, test and deploy, which makes it great for small teams. <b>Microservices</b> split it into many small apps, each owning one job and its own data. Teams can work and scale independently, but you now deal with network calls, failures between services, and a lot more to run.</p><p>Sensible path: start with a <b>modular monolith</b> (one app, cleanly separated inside), and split off a service only when there's a clear reason, like a part that needs to scale very differently.</p>`,
w:[["Monolith","One application and codebase that contains all features."],["Microservices","Many small, independently deployed services."],["Modular monolith","One app with clean internal boundaries between features."],["Event-driven","Services react to events (\"OrderPlaced\") instead of calling each other directly."],["CQRS","Using separate models for writing data and for reading it."],["Service discovery","How services find each other's current network addresses."]]},

/* ---------- World 5: Distributed Systems ---------- */
"consensus":{p:`<p>Several machines must agree on something, like who's the boss (the <b>leader</b>) or what the latest value is, even if some crash. They vote, and a <b>majority</b> wins. With 3 machines you can lose 1; with 5 you can lose 2. In general, 2f+1 machines survive f failures.</p><p><b>Raft</b> and <b>Paxos</b> are the well-known voting rules. You almost never build these yourself; you use tools like <b>ZooKeeper</b> or <b>etcd</b> that already do it, for leader election, distributed locks and shared config.</p>`,
w:[["Consensus","Machines agreeing on one value despite failures."],["Leader election","Choosing one machine to coordinate the others."],["Quorum / majority","More than half of the machines."],["Raft","A popular, understandable consensus algorithm."],["Distributed lock","A lock that machines across the network respect."],["etcd / ZooKeeper","Ready-made coordination services built on consensus."]]},
"ids-clocks":{p:`<p>In one database, IDs can just count up: 1, 2, 3. Across many machines that breaks, because two machines could both hand out "1001". Options: <b>UUIDs</b> (random 128-bit IDs that practically never clash, but they're long and unsorted) or <b>Snowflake IDs</b> (a 64-bit number built from the time + machine number + a counter, so they're unique and roughly sorted by time).</p><p>Also, computer clocks drift a little, so you can't fully trust timestamps to order events across machines. <b>Logical clocks</b> order events by counting instead of by wall time.</p>`,
w:[["Auto-increment","A DB column that counts up 1, 2, 3 automatically."],["UUID","A random 128-bit ID that's practically unique without coordination."],["Snowflake ID","A 64-bit ID made of timestamp + machine ID + sequence number."],["Clock drift","Machine clocks slowly disagreeing with each other."],["Logical clock","A counter used to order events without trusting wall-clock time."],["Monotonic","Only ever goes up, never back."]]},
"prob-ds":{p:`<p>Sometimes an <i>almost</i> right answer using tiny memory beats an exact answer using huge memory. A <b>Bloom filter</b> answers "have I seen this?" It can say "definitely no" or "probably yes", which is perfect for skipping pointless database lookups. <b>HyperLogLog</b> estimates "how many unique visitors?" within about 1% using just kilobytes. <b>Count-Min sketch</b> estimates "how often did this appear?" for finding trending items.</p>`,
w:[["Probabilistic data structure","A structure that trades a small, known error for huge memory savings."],["False positive","Saying \"yes\" when the true answer is \"no\"."],["Bloom filter","A bit array + hash functions that tests membership; no false negatives."],["HyperLogLog","Estimates the number of unique items using very little memory."],["Count-Min sketch","Estimates how often items occur; good for top-K."],["Cardinality","The number of distinct items."]]},
"streaming":{p:`<p><b>Batch processing</b> is like doing laundry once a week: collect everything, then process it all together. Good for daily reports and bills. <b>Stream processing</b> is like washing each dish as soon as it's used: handle every event the moment it arrives. Good for fraud alerts and live counters.</p><p>Streams bring new questions: events can arrive late or out of order, and you often count within time <b>windows</b> ("clicks per minute"). <b>CDC</b> (change data capture) turns every database change into a stream event so other systems stay in sync.</p>`,
w:[["Batch processing","Processing a large, fixed chunk of data on a schedule."],["Stream processing","Processing events continuously as they arrive."],["Event","A record that something happened, e.g. \"user clicked ad 12 at 10:01\"."],["Window","A time slice used to group events, e.g. each 1 minute."],["CDC","Change data capture: turning DB changes into a stream of events."],["Late event","An event that arrives after its time window has already been counted."]]},

/* ---------- World 6: Interview Craft ---------- */
"framework":{p:`<p>Design interviews feel scary because the question is huge ("design WhatsApp"). The secret: <b>use the same 7 steps every time</b>, like a recipe. Ask what it must do (<b>requirements</b>) → rough numbers (<b>estimates</b>) → the main things it stores (<b>entities</b>) → how apps talk to it (<b>API</b>) → a simple boxes-and-arrows drawing (<b>high-level design</b>) → zoom into the hardest parts (<b>deep dives</b>) → summarise.</p><p>Interviewers care more about clear thinking and talking through choices than about knowing every tool.</p>`,
w:[["Functional requirements","What the system must do, e.g. \"users can send messages\"."],["Non-functional requirements","How well it must do it: speed, availability, scale, security."],["Entity","A main thing the system stores, like User, Message, Order."],["High-level design","The boxes-and-arrows diagram of main components."],["Deep dive","Zooming into one hard part and discussing options in detail."],["Bottleneck","The part that limits the whole system's speed or scale."]]},
"estimation":{p:`<p>Interviewers want rough numbers, not exact maths, to decide things like "do we need caching?" or "will one database be enough?". Round boldly: a day has 86,400 seconds, call it 100,000 (10⁵). So 1 million requests a day is about 12 per second. Peak traffic is often 2–3× the average.</p><p>Always say the steps out loud (users × actions ÷ seconds) and finish with what the number means: "~350k reads per second, so we definitely need a cache."</p>`,
w:[["QPS","Queries (requests) per second."],["Peak","The busiest moment's traffic, usually 2–3× the average."],["DAU","Daily active users."],["Read:write ratio","How many reads happen for every write."],["KB / MB / GB / TB","Each is about 1,000× the previous: kilobyte → megabyte → gigabyte → terabyte."],["Back-of-the-envelope","Quick, rough calculation to get the order of magnitude."]]},
"tradeoffs":{p:`<p>Every design choice gives something up. Cache = faster, but data may be slightly old. SQL = safe and structured, but harder to spread across machines. Async queue = smoother, but the result isn't instant.</p><p>Strong answers say it in one breath: <i>"I'll pick X because we need Y; the cost is Z, which is fine here because…"</i>. This section collects the classic pairs and the mistakes beginners make, like jumping into drawing before asking any questions.</p>`,
w:[["Trade-off","Choosing one benefit at the cost of another."],["Over-engineering","Adding complexity the requirements don't need."],["Strong consistency","Everyone always sees the latest data."],["Eventual consistency","Data may be briefly out of date but catches up."],["Premature optimisation","Optimising before you know where the real problem is."]]},

/* ---------- World 7: Low-Level Design ---------- */
"oop-solid":{p:`<p><b>Object-oriented programming</b> groups data and the functions that use it into <b>classes</b>. A <code>BankAccount</code> class holds a balance and has <code>deposit()</code> and <code>withdraw()</code>. You hide the inside details (<b>encapsulation</b>), reuse and extend behaviour (<b>inheritance</b>), and treat different classes the same way through a shared interface (<b>polymorphism</b>).</p><p><b>SOLID</b> is five habits that keep code easy to change, such as "each class has one job" and "add new behaviour by adding new classes, not by editing old ones".</p>`,
w:[["Class / object","A class is a blueprint; an object is one thing built from it."],["Encapsulation","Keeping data private and exposing only safe methods."],["Inheritance","A class reusing and extending another class."],["Polymorphism","Different classes answering the same method call in their own way."],["Interface / abstract class","A contract listing methods a class must provide."],["Composition","Building a class from other objects (has-a) instead of inheriting (is-a)."]]},
"patterns":{p:`<p><b>Design patterns</b> are proven recipes for common code problems, each with a name so developers can talk quickly. Need to swap pricing rules at runtime? <b>Strategy</b>. Need many parts notified when something changes? <b>Observer</b>. An object behaving differently in each stage (Draft → Submitted → Approved)? <b>State</b>. Creating the right kind of object without lots of if-else? <b>Factory</b>.</p><p>Use a pattern only when it solves a real problem in your design. Forcing patterns in looks worse than using none.</p>`,
w:[["Design pattern","A named, reusable solution to a common design problem."],["Strategy","Swap one algorithm for another behind the same interface."],["Observer","Subscribers get notified automatically when something changes."],["State","An object changes behaviour based on its current state object."],["Factory","A method or class that decides which object to create."],["Singleton","A class allowed only one instance."]]},
"lld-round":{p:`<p>In a machine-coding round you get 45–90 minutes to design and code something like a parking lot or an elevator. Don't start typing straight away. First <b>clarify</b> what's in scope, list the main <b>entities</b> (nouns become classes, verbs become methods), sketch how they relate, then write the core classes, and finally a small <b>driver</b> (a main function) that shows it working.</p><p>Finish by explaining how a new feature would fit in, and what happens if two users act at the same moment (<b>concurrency</b>).</p>`,
w:[["Machine-coding round","An interview where you write working, well-structured code for a small system."],["Entity","A main noun in the problem that becomes a class."],["Driver / demo","A small main program that exercises your classes."],["Extensibility","How easily new features can be added."],["Concurrency","Multiple threads or users acting at the same time."],["Race condition","A bug where the result depends on the timing of two actions."]]},

/* ---------- World 8: AI System Design ---------- */
"llm-apps":{p:`<p>A chatbot looks like "send question, get answer", but a real product has a pipeline around the model. It collects useful context, checks the input is safe, picks a model, generates the answer, checks the output, and logs everything so you can measure quality.</p><p>Models read and write text as <b>tokens</b> (pieces of words; roughly ¾ of an English word each). You pay per token and longer outputs take longer, so tokens drive both cost and speed. <b>Temperature</b> controls randomness: low for factual answers, higher for creative writing.</p>`,
w:[["LLM","Large language model: an AI model that predicts and generates text."],["Prompt","The input text you send to the model."],["Token","A chunk of text (part of a word) that models read and bill by."],["Context window","The maximum number of tokens a model can consider at once."],["Temperature","A setting that controls how random or creative the output is."],["Guardrail","A check that blocks unsafe input or output."]]},
"rag":{p:`<p>An LLM doesn't know your company's documents. <b>RAG</b> (retrieval-augmented generation) fixes that like an open-book exam: first <b>find</b> the relevant pages, then let the model <b>answer using them</b>, with citations.</p><p>Beforehand, you split documents into small pieces (<b>chunks</b>), turn each into an <b>embedding</b> (numbers that capture meaning), and store them in a vector index. At question time you embed the question, fetch the closest chunks, optionally <b>rerank</b> them for better order, and put the best ones in the prompt. Permission filters make sure people only see documents they're allowed to.</p>`,
w:[["RAG","Retrieve relevant documents, then generate an answer grounded in them."],["Chunk","A small piece of a document, e.g. ~500 tokens."],["Embedding","Numbers representing the meaning of text."],["Vector database","Stores embeddings and finds the most similar ones fast."],["Rerank","Re-scoring retrieved chunks with a more accurate model."],["Hallucination","When a model states something false with confidence."],["Fine-tuning","Further training a model on your own examples."]]},
"agents":{p:`<p>An <b>agent</b> is an LLM that decides which <b>tools</b> to use (search, calculator, database, send email) in a loop until the task is done. It's powerful but less predictable. If the steps are always the same, a fixed <b>workflow</b> (step 1 → step 2 → step 3) is cheaper and more reliable, so use that first.</p><p>Before shipping, test with <b>evals</b>: a set of real questions with known good answers, scored automatically. Add <b>guardrails</b> against tricks like prompt injection, and only give the agent the permissions it truly needs.</p>`,
w:[["Agent","An LLM that chooses and calls tools in a loop to reach a goal."],["Tool / function calling","Letting the model request an action, like calling an API."],["Workflow","A fixed sequence of LLM and code steps."],["Eval","An automated test set that scores model outputs."],["Prompt injection","Malicious text that tries to make the model ignore its instructions."],["PII","Personally identifiable information, like phone numbers or addresses."]]},
"llm-serving":{p:`<p>Running your own model needs GPUs, and GPU memory is the main limit. It must hold the model's <b>weights</b> plus a working memory for each active conversation (the <b>KV cache</b>). Serving engines like vLLM process many users' requests together (<b>continuous batching</b>) to get far more answers per GPU.</p><p>For companies you also add separation between customers (<b>tenant isolation</b>), audit logs of who asked what, and spending limits per team.</p>`,
w:[["GPU","A chip that does many calculations in parallel; used to run AI models."],["Weights","The learned numbers that make up a model."],["KV cache","Saved intermediate results per conversation so the model doesn't recompute earlier tokens."],["Batching","Processing several requests together for efficiency."],["Inference","Running a trained model to get an output."],["Tenant","One customer organisation sharing the platform."],["TTFT","Time to first token: how long before the answer starts appearing."]]}
};

/* ---------- Problems: what you're building, in plain words ---------- */
const PEASY={
"url-shortener":"Build something like bit.ly. You paste a long, messy link and get a short one like <code>sho.rt/aB3xY9</code>. When anyone opens the short link, they're instantly sent to the long one. Far more people <i>open</i> links than <i>create</i> them, so making the redirect fast is the heart of it.",
"rate-limiter":"Build the bouncer that sits in front of an API and says \"you've made too many requests, slow down\". For example: at most 100 requests per minute per user. It must be very fast (it runs on every request) and give the same answer no matter which server the request hits.",
"unique-id":"Build a service that hands out unique ID numbers, like order numbers, to many servers at once, thousands per second, with no two ever the same, and ideally sorted roughly by time so newer items have bigger IDs.",
"notification":"Build the one service every other team calls to send a push notification, SMS or email. It has to respect user settings (\"no promo emails\"), retry when a provider fails, and cope with a marketing blast to millions without delaying important messages like OTPs.",
"chat":"Build a WhatsApp-style chat. Messages between two people (and groups) should arrive instantly when online, be saved for later when offline, keep their order, and show ticks for sent, delivered and read.",
"news-feed":"Build the home feed of an app like Instagram or Twitter: when you open the app, show recent posts from people you follow, newest or best first, in well under a second, even for users who follow thousands of accounts.",
"dropbox":"Build a Google Drive / Dropbox clone: upload files from any device, see them on all your devices, share them, and keep old versions. Big files should upload in pieces so a dropped Wi-Fi doesn't mean starting over.",
"youtube":"Build a video site. People upload videos; the system converts each into several qualities (360p to 4K); viewers anywhere stream smoothly, and the quality adjusts to their internet speed.",
"autocomplete":"Build the search box suggestions you see while typing: after \"how to b\", show the top 5 popular completions. It must respond in a few milliseconds per keystroke and reflect what's trending.",
"web-crawler":"Build a program that visits web pages, saves them, finds the links on each page, and visits those too, eventually covering billions of pages, without visiting the same page twice or flooding any one website with requests.",
"uber":"Build the core of a ride-hailing app: drivers send their location every few seconds; a rider requests a ride; the system finds a nearby available driver quickly and makes sure two riders never get the same driver.",
"ticketmaster":"Build a ticket booking site for concerts or movies. Thousands of fans rush in at the same second for limited seats. Show availability, hold a seat for a few minutes while someone pays, and never sell the same seat twice.",
"payment":"Build the system that lets an online shop charge customers through a payment provider. Above all: never charge someone twice, never lose a payment, and keep a record that always adds up, even when networks fail mid-payment.",
"job-scheduler":"Build a system that runs tasks at the right time: \"send this reminder in 48 hours\", \"run this report every day at 9 am\". Jobs must run on time, retry if they fail, and not be lost or run twice when a machine crashes.",
"leaderboard":"Build a live game leaderboard: players' scores change constantly, and anyone can instantly see the top 100 and their own rank among millions of players.",
"ad-click":"Build the counter behind online ads: record every click on every ad (huge volume), and let advertisers see near-real-time totals like \"clicks per minute for ad 42\", accurate enough to bill money on.",
"kv-store":"Build your own simple database that stores values by key (like a giant dictionary) across many machines, so it keeps working and keeps the data even when some machines die.",
"workflow-engine":"Build a low-code tool where a company admin designs a form and an approval flow (e.g. leave request → manager → HR). Employees submit, approvers approve or reject, reminders go out if someone is slow, and every step is recorded. Many companies share the same platform.",
"rag-qa":"Build a chatbot that answers employees' questions using the company's own documents, shows which document each answer came from, and never reveals documents a person isn't allowed to see.",
"llm-gateway":"Build one central door that every team in a company uses to call AI models. It handles keys, picks the right model, limits spending per team, caches repeated questions, logs usage, and switches provider if one goes down.",
"parking-lot-hld":"Build the backend for a chain of parking lots: cars enter and get a ticket, the system tracks free spots by size, and charges by time on exit. It's a classic warm-up that tests clean modelling more than huge scale."
};

/* ---------- Glossary: every new word, plus a few extras ---------- */
const GLOSSARY=(()=>{const g={};Object.values(EASY).forEach(e=>e.w.forEach(([k,v])=>{if(!g[k])g[k]=v;}));
  [["Request","A message from a client asking a server to do something."],["Response","The server's reply to a request."],["Client","The app or browser that sends requests (your phone, laptop)."],["Node","One machine in a group of machines."],["Cluster","A group of machines working together."],["Throughput","How many requests the system completes per second."],["Stale data","Old data that hasn't caught up with the latest change yet."],["Fan-out","Sending one thing to many places, e.g. one post to all followers' feeds."],["Denormalisation","Storing duplicate data on purpose so reads don't need joins."],["Heartbeat","A regular \"I'm alive\" signal a machine sends."],["Backpressure","Slowing down producers when consumers can't keep up."],["Webhook","A URL another service calls to tell you something happened."],["Kubernetes","A system that runs and manages containers across many machines."],["Container","A packaged app with everything it needs to run, e.g. a Docker image."]].forEach(([k,v])=>{if(!g[k])g[k]=v;});
  return g;})();
